-- Source: sql/validation/09_reconciliation.sql
{{ config(materialized='view') }}

SELECT
  s.sales_lines,
  s.gross_sales,
  s.discount_value,
  s.sales_revenue,
  s.cost_of_sales,
  s.units_sold,
  s.transactions,
  s.promo_sales_revenue,
  r.returns_rows,
  r.returns_value,
  r.restock_cost_credit,
  i.inventory_cells_2024,
  i.in_stock_cells_2024,
  h.h2_2024_sales_revenue,
  h.h2_2025_sales_revenue,
  hr.h2_2024_returns_value,
  hr.h2_2025_returns_value
FROM (
  SELECT
    COUNT(*) AS sales_lines,
    CAST(SUM(gross_amount) AS DECIMAL(19, 2)) AS gross_sales,
    CAST(SUM(discount_amount) AS DECIMAL(19, 2)) AS discount_value,
    CAST(SUM(sales_revenue) AS DECIMAL(19, 2)) AS sales_revenue,
    CAST(SUM(cost_amount) AS DECIMAL(19, 2)) AS cost_of_sales,
    SUM(CAST(quantity AS INT)) AS units_sold,
    COUNT(DISTINCT transaction_id) AS transactions,
    CAST(SUM(CASE WHEN is_promoted = 1 THEN sales_revenue ELSE 0 END) AS DECIMAL(19, 2)) AS promo_sales_revenue
  FROM {{ ref('fact_sales') }}
) AS s
CROSS JOIN (
  SELECT
    COUNT(*) AS returns_rows,
    CAST(SUM(refund_value) AS DECIMAL(19, 2)) AS returns_value,
    CAST(SUM(restock_cost_credit) AS DECIMAL(19, 4)) AS restock_cost_credit
  FROM {{ ref('fact_returns') }}
) AS r
CROSS JOIN (
  SELECT
    COUNT(*) AS inventory_cells_2024,
    SUM(CAST(f.is_in_stock AS INT)) AS in_stock_cells_2024
  FROM {{ ref('fact_inventory') }} AS f
  JOIN {{ ref('dim_date') }} AS d
    ON d.date_key = f.snapshot_date_key
  WHERE
    d.retail_year = 2024
) AS i
CROSS JOIN (
  SELECT
    CAST(SUM(CASE WHEN d.retail_year = 2024 THEN f.sales_revenue ELSE 0 END) AS DECIMAL(19, 2)) AS h2_2024_sales_revenue,
    CAST(SUM(CASE WHEN d.retail_year = 2025 THEN f.sales_revenue ELSE 0 END) AS DECIMAL(19, 2)) AS h2_2025_sales_revenue
  FROM {{ ref('fact_sales') }} AS f
  JOIN {{ ref('dim_date') }} AS d
    ON d.date_key = f.date_key
  WHERE
    d.retail_week BETWEEN 27 AND 52
) AS h
CROSS JOIN (
  SELECT
    CAST(SUM(CASE WHEN d.retail_year = 2024 THEN f.refund_value ELSE 0 END) AS DECIMAL(19, 2)) AS h2_2024_returns_value,
    CAST(SUM(CASE WHEN d.retail_year = 2025 THEN f.refund_value ELSE 0 END) AS DECIMAL(19, 2)) AS h2_2025_returns_value
  FROM {{ ref('fact_returns') }} AS f
  JOIN {{ ref('dim_date') }} AS d
    ON d.date_key = f.return_date_key
  WHERE
    d.retail_week BETWEEN 27 AND 52
) AS hr
